#!/usr/bin/env python3
"""Bidirectional Key-Segment stream engine.

Implements:
  main.py compile          - read config JSON on stdin, emit compiled program JSON
  main.py stream <prog>    - read requests per line, emit one JSON response per line

Matching uses an output-sensitive Shift-And automaton over a single Python
integer bitset: each rule's positions occupy a contiguous block separated by a
dead bit, and per-feature-value masks are precomputed by a linear sweep.
"""
import sys
import json
import heapq

sys.set_int_max_str_digits(8192)

INT32_MAX = 2**31 - 1
INT32_MIN = -2**31
TIME_MAX = 2**53 - 1


# ---------------------------------------------------------------------------
# JSON helpers
# ---------------------------------------------------------------------------
class BadJSON(Exception):
    pass


def _reject_const(x):
    raise BadJSON("non-finite constant")


def _no_dup(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise BadJSON("duplicate key")
        d[k] = v
    return d


def parse_json_text(text):
    return json.loads(text, object_pairs_hook=_no_dup, parse_constant=_reject_const)


def is_int(x):
    return type(x) is int


# ---------------------------------------------------------------------------
# Configuration validation (compile)
# ---------------------------------------------------------------------------
class ConfigError(Exception):
    pass


def _req_int(x, lo, hi):
    if not is_int(x):
        raise ConfigError()
    if x < lo or x > hi:
        raise ConfigError()
    return x


def validate_config(cfg):
    if not isinstance(cfg, dict):
        raise ConfigError()
    if set(cfg.keys()) != {"version", "idle_timeout", "packet_limit",
                           "prefix_width", "rules", "fallback"}:
        raise ConfigError()

    if not is_int(cfg["version"]) or cfg["version"] != 1:
        raise ConfigError()

    idle_timeout = _req_int(cfg["idle_timeout"], 0, 10**9)
    packet_limit = _req_int(cfg["packet_limit"], 1, 10**9)
    W = _req_int(cfg["prefix_width"], 1, 32)

    rules_raw = cfg["rules"]
    if not isinstance(rules_raw, list):
        raise ConfigError()
    if len(rules_raw) > 2048:
        raise ConfigError()

    rules = []
    seen_ids = set()
    total_positions = 0
    for r in rules_raw:
        if not isinstance(r, dict):
            raise ConfigError()
        if set(r.keys()) != {"id", "class", "priority", "ranges"}:
            raise ConfigError()
        rid = _req_int(r["id"], 0, INT32_MAX)
        rcls = _req_int(r["class"], 0, 65535)
        rprio = _req_int(r["priority"], INT32_MIN, INT32_MAX)
        if rid in seen_ids:
            raise ConfigError()
        seen_ids.add(rid)
        ranges_raw = r["ranges"]
        if not isinstance(ranges_raw, list):
            raise ConfigError()
        if len(ranges_raw) < 1 or len(ranges_raw) > 32:
            raise ConfigError()
        total_positions += len(ranges_raw)
        if total_positions > 16384:
            raise ConfigError()
        ranges = []
        for rg in ranges_raw:
            if not isinstance(rg, list) or len(rg) != 2:
                raise ConfigError()
            lo = _req_int(rg[0], -2048, 2048)
            hi = _req_int(rg[1], -2048, 2048)
            if lo > hi:
                raise ConfigError()
            ranges.append((lo, hi))
        rules.append((rid, rcls, rprio, ranges))

    fb = cfg["fallback"]
    node_count = [0]
    max_depth = [0]

    def walk(node, depth):
        if depth > 16:
            raise ConfigError()
        if not isinstance(node, dict):
            raise ConfigError()
        node_count[0] += 1
        if node_count[0] > 255:
            raise ConfigError()
        keys = set(node.keys())
        if keys == {"class"}:
            _req_int(node["class"], 0, 65535)
            if depth > max_depth[0]:
                max_depth[0] = depth
            return
        if keys == {"feature", "threshold", "le", "gt"}:
            _req_int(node["feature"], 0, W - 1)
            _req_int(node["threshold"], -2048, 2048)
            walk(node["le"], depth + 1)
            walk(node["gt"], depth + 1)
            return
        raise ConfigError()

    walk(fb, 0)

    return {
        "idle_timeout": idle_timeout,
        "packet_limit": packet_limit,
        "prefix_width": W,
        "rules": rules,
        "fallback": fb,
    }


def program_from_config(cfg):
    return {
        "idle_timeout": cfg["idle_timeout"],
        "packet_limit": cfg["packet_limit"],
        "prefix_width": cfg["prefix_width"],
        "rules": [[rid, rcls, rprio, [[lo, hi] for lo, hi in ranges]]
                  for (rid, rcls, rprio, ranges) in cfg["rules"]],
        "fallback": cfg["fallback"],
    }


# ---------------------------------------------------------------------------
# Matcher: Shift-And over a single big integer
# ---------------------------------------------------------------------------
class Matcher(object):
    def __init__(self, rules):
        n = len(rules)
        self.k = [len(r[3]) for r in rules]
        self.rid = [r[0] for r in rules]
        self.cls = [r[1] for r in rules]
        self.prio = [r[2] for r in rules]

        base = 0
        self.base = []
        self.term_bit = []
        START = 0
        TERM = 0
        for idx, r in enumerate(rules):
            k = len(r[3])
            self.base.append(base)
            tb = base + k - 1
            self.term_bit.append(tb)
            START |= (1 << base)
            TERM |= (1 << tb)
            base += k + 1
        self.START = START
        self.TERM = TERM
        self.P = base

        tbmap = {}
        for idx, tb in enumerate(self.term_bit):
            tbmap[tb] = idx
        self.tbmap = tbmap

        V = 4097
        OFF = 2048
        self.OFF = OFF
        add_at = [[] for _ in range(V)]
        rem_at = [[] for _ in range(V)]
        for idx, r in enumerate(rules):
            b = self.base[idx]
            for i, (lo, hi) in enumerate(r[3]):
                p = b + i
                alo = lo + OFF
                if alo < 0:
                    alo = 0
                ahi = hi + OFF
                if ahi > V - 1:
                    ahi = V - 1
                if alo <= ahi:
                    add_at[alo].append(p)
                    if ahi + 1 <= V - 1:
                        rem_at[ahi + 1].append(p)
        B = [0] * V
        cur = 0
        for v in range(V):
            for p in add_at[v]:
                cur |= (1 << p)
            for p in rem_at[v]:
                cur ^= (1 << p)
            B[v] = cur
        self.B = B
        self.maxlen = max(self.k) if self.k else 0

    def step(self, D, v):
        return ((D << 1) | self.START) & self.B[v + self.OFF]

    def replay(self, feats):
        D = 0
        step = self.step
        for v in feats:
            D = step(D, v)
        return D


# ---------------------------------------------------------------------------
# Runtime
# ---------------------------------------------------------------------------
class EventError(Exception):
    pass


class Flow(object):
    __slots__ = ("fid", "last", "n", "fwd", "decided", "cls", "reason",
                 "rule", "mcount", "first", "lastfeat", "D")

    def __init__(self):
        self.fid = 0
        self.last = 0
        self.n = 0
        self.fwd = None
        self.decided = False
        self.cls = None
        self.reason = None
        self.rule = None
        self.mcount = 0
        self.first = []
        self.lastfeat = []
        self.D = 0


REASON_CODE = {"key": 0, "idle": 1, "packet_limit": 2, "end": 3}
CODE_REASON = {0: "key", 1: "idle", 2: "packet_limit", 3: "end"}


class Engine(object):
    def __init__(self, prog):
        self.idle_timeout = prog["idle_timeout"]
        self.packet_limit = prog["packet_limit"]
        self.W = prog["prefix_width"]

        rules = [(r[0], r[1], r[2], [(x[0], x[1]) for x in r[3]])
                 for r in prog["rules"]]
        self.matcher = Matcher(rules)
        self.maxlen = self.matcher.maxlen
        self.hasmatch = self.maxlen > 0

        # fallback tree compiled to arrays
        self.tree = []
        self.tree_root = self._build_tree(prog["fallback"])

        self.flows = {}
        self.heap = []
        self.last_time = -1

    # -- fallback tree ------------------------------------------------------
    def _build_tree(self, node):
        if "class" in node:
            idx = len(self.tree)
            self.tree.append(("c", node["class"]))
            return idx
        idx = len(self.tree)
        self.tree.append(None)
        le = self._build_tree(node["le"])
        gt = self._build_tree(node["gt"])
        self.tree[idx] = ("i", node["feature"], node["threshold"], le, gt)
        return idx

    def _tree_eval(self, feats):
        i = self.tree_root
        tree = self.tree
        while True:
            nd = tree[i]
            if nd[0] == "c":
                return nd[1]
            if feats[nd[1]] <= nd[2]:
                i = nd[3]
            else:
                i = nd[4]

    def backup_class(self, f):
        feats = f.first
        need = self.W - len(feats)
        if need > 0:
            feats = feats + [0] * need
        return self._tree_eval(feats)

    # -- heap ---------------------------------------------------------------
    def _rebuild_heap(self):
        self.heap = [(f.last, fid) for fid, f in self.flows.items()
                     if not f.decided]
        heapq.heapify(self.heap)

    # -- expiry -------------------------------------------------------------
    def expire(self, T):
        thr = T - self.idle_timeout
        heap = self.heap
        expired = []
        while heap and heap[0][0] < thr:
            la, fid = heapq.heappop(heap)
            f = self.flows.get(fid)
            if f is None or f.decided:
                continue
            if f.last != la:
                continue
            expired.append(fid)
        if not expired:
            return []
        if len(expired) > 1:
            expired.sort()
        ev = []
        for fid in expired:
            f = self.flows.get(fid)
            if f is None or f.decided:
                continue
            cls = self.backup_class(f)
            f.decided = True
            f.cls = cls
            f.reason = "idle"
            f.rule = None
            ev.append({"type": "decision", "flow": fid, "class": cls,
                       "reason": "idle", "at": f.n, "time": T, "rule": None})
        return ev

    # -- packet processing --------------------------------------------------
    def add_packet(self, f, source, length, T):
        if f.fwd is None:
            f.fwd = source
        v = length if source == f.fwd else -length
        f.n += 1
        f.last = T
        if len(f.first) < self.W:
            f.first.append(v)
        events = []

        if self.hasmatch:
            m = self.matcher
            lf = f.lastfeat
            lf.append(v)
            if len(lf) > self.maxlen:
                del lf[0]
            D = m.step(f.D, v)
            f.D = D
            t = D & m.TERM
            if t:
                matched = []
                while t:
                    low = t & -t
                    b = low.bit_length() - 1
                    idx = m.tbmap[b]
                    matched.append(idx)
                    t ^= low
                # emit in ascending rule id order
                matched.sort(key=lambda ix: m.rid[ix])
                for idx in matched:
                    k = m.k[idx]
                    events.append({"type": "match", "flow": f.fid,
                                   "rule": m.rid[idx],
                                   "start": f.n - k, "end": f.n})
                    f.mcount += 1
                if not f.decided:
                    best = None
                    for idx in matched:
                        key = (m.prio[idx], m.k[idx], -m.rid[idx])
                        if best is None or key > best[0]:
                            best = (key, idx)
                    bidx = best[1]
                    f.decided = True
                    f.cls = m.cls[bidx]
                    f.reason = "key"
                    f.rule = m.rid[bidx]
                    events.append({"type": "decision", "flow": f.fid,
                                   "class": m.cls[bidx], "reason": "key",
                                   "at": f.n, "time": T, "rule": m.rid[bidx]})

        if not f.decided and f.n >= self.packet_limit:
            cls = self.backup_class(f)
            f.decided = True
            f.cls = cls
            f.reason = "packet_limit"
            f.rule = None
            events.append({"type": "decision", "flow": f.fid, "class": cls,
                           "reason": "packet_limit", "at": f.n, "time": T,
                           "rule": None})

        if not f.decided:
            heapq.heappush(self.heap, (T, f.fid))
            if len(self.heap) > 8192:
                self._rebuild_heap()
        return events

    # -- request handling ---------------------------------------------------
    def handle(self, req, first):
        if not isinstance(req, dict):
            raise EventError()
        op = req.get("op")
        if not isinstance(op, str):
            raise EventError()

        if op == "restore":
            if not first:
                raise EventError()
            if set(req.keys()) != {"op", "checkpoint"}:
                raise EventError()
            self._restore(req["checkpoint"])
            return {"events": []}

        if op == "checkpoint":
            if set(req.keys()) != {"op"}:
                raise EventError()
            return {"checkpoint": self._checkpoint()}

        if op == "open":
            if set(req.keys()) != {"op", "flow", "time"}:
                raise EventError()
            fid = req["flow"]
            T = req["time"]
            if not is_int(fid) or not (0 <= fid <= INT32_MAX):
                raise EventError()
            if not is_int(T) or not (0 <= T <= TIME_MAX):
                raise EventError()
            if T < self.last_time:
                raise EventError()
            if fid in self.flows:
                raise EventError()
            if len(self.flows) >= 4096:
                raise EventError()
            events = self.expire(T)
            f = Flow()
            f.fid = fid
            f.last = T
            self.flows[fid] = f
            heapq.heappush(self.heap, (T, fid))
            self.last_time = T
            return {"events": events}

        if op == "tick":
            if set(req.keys()) != {"op", "time"}:
                raise EventError()
            T = req["time"]
            if not is_int(T) or not (0 <= T <= TIME_MAX):
                raise EventError()
            if T < self.last_time:
                raise EventError()
            events = self.expire(T)
            self.last_time = T
            return {"events": events}

        if op == "close":
            if set(req.keys()) != {"op", "flow", "time"}:
                raise EventError()
            fid = req["flow"]
            T = req["time"]
            if not is_int(fid) or not (0 <= fid <= INT32_MAX):
                raise EventError()
            if not is_int(T) or not (0 <= T <= TIME_MAX):
                raise EventError()
            if T < self.last_time:
                raise EventError()
            f = self.flows.get(fid)
            if f is None:
                raise EventError()
            events = self.expire(T)
            if not f.decided:
                cls = self.backup_class(f)
                f.decided = True
                f.cls = cls
                f.reason = "end"
                f.rule = None
                events.append({"type": "decision", "flow": fid, "class": cls,
                               "reason": "end", "at": f.n, "time": T,
                               "rule": None})
            events.append({"type": "closed", "flow": fid, "packets": f.n,
                           "matches": f.mcount, "class": f.cls,
                           "reason": f.reason, "rule": f.rule})
            del self.flows[fid]
            self.last_time = T
            return {"events": events}

        if op == "chunk":
            if set(req.keys()) != {"op", "packets"}:
                raise EventError()
            packets = req["packets"]
            if not isinstance(packets, list):
                raise EventError()
            if len(packets) > 1024:
                raise EventError()
            events = []
            for p in packets:
                if not isinstance(p, dict):
                    raise EventError()
                if set(p.keys()) != {"flow", "time", "source", "length"}:
                    raise EventError()
                fid = p["flow"]
                t = p["time"]
                src = p["source"]
                L = p["length"]
                if not is_int(fid) or not (0 <= fid <= INT32_MAX):
                    raise EventError()
                if not is_int(t) or not (0 <= t <= TIME_MAX):
                    raise EventError()
                if not is_int(src) or (src != 0 and src != 1):
                    raise EventError()
                if not is_int(L) or not (1 <= L <= 2048):
                    raise EventError()
                if t < self.last_time:
                    raise EventError()
                f = self.flows.get(fid)
                if f is None:
                    raise EventError()
                ev = self.expire(t)
                if ev:
                    events.extend(ev)
                ev = self.add_packet(f, src, L, t)
                if ev:
                    events.extend(ev)
                self.last_time = t
            return {"events": events}

        raise EventError()

    # -- checkpoint / restore ----------------------------------------------
    def _checkpoint(self):
        fl = []
        for fid, f in self.flows.items():
            fl.append([
                f.fid, f.last, f.n,
                -1 if f.fwd is None else f.fwd,
                1 if f.decided else 0,
                -1 if f.cls is None else f.cls,
                -1 if f.reason is None else REASON_CODE[f.reason],
                -1 if f.rule is None else f.rule,
                f.mcount,
                list(f.first),
                list(f.lastfeat),
            ])
        return {"t": self.last_time, "fl": fl}

    def _restore(self, val):
        if not isinstance(val, dict):
            raise EventError()
        if set(val.keys()) != {"t", "fl"}:
            raise EventError()
        t = val["t"]
        fl = val["fl"]
        if not is_int(t):
            raise EventError()
        if not isinstance(fl, list):
            raise EventError()
        self.flows = {}
        self.heap = []
        self.last_time = t
        for e in fl:
            if not isinstance(e, list) or len(e) != 11:
                raise EventError()
            f = Flow()
            f.fid = e[0]
            f.last = e[1]
            f.n = e[2]
            f.fwd = None if e[3] == -1 else e[3]
            f.decided = bool(e[4])
            f.cls = None if e[5] == -1 else e[5]
            f.reason = None if e[6] == -1 else CODE_REASON[e[6]]
            f.rule = None if e[7] == -1 else e[7]
            f.mcount = e[8]
            f.first = list(e[9])
            f.lastfeat = list(e[10])
            if self.hasmatch and f.lastfeat:
                f.D = self.matcher.replay(f.lastfeat)
            else:
                f.D = 0
            self.flows[f.fid] = f
            if not f.decided:
                heapq.heappush(self.heap, (f.last, f.fid))


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------
def cmd_compile():
    try:
        raw = sys.stdin.buffer.read()
    except Exception:
        sys.stdout.write('{"error":"config"}')
        return 2
    try:
        text = raw.decode("utf-8")
    except Exception:
        sys.stdout.write('{"error":"config"}')
        return 2
    try:
        cfg = parse_json_text(text)
    except Exception:
        sys.stdout.write('{"error":"config"}')
        return 2
    try:
        validated = validate_config(cfg)
    except ConfigError:
        sys.stdout.write('{"error":"config"}')
        return 2
    except Exception:
        sys.stdout.write('{"error":"config"}')
        return 2
    prog = program_from_config(validated)
    out = json.dumps(prog, separators=(",", ":"))
    sys.stdout.write(out)
    return 0


def cmd_stream(path):
    try:
        with open(path, "r", encoding="utf-8") as fh:
            prog = json.load(fh)
    except Exception:
        return 2
    engine = Engine(prog)

    stdin = sys.stdin.buffer
    stdout = sys.stdout
    first = True

    while True:
        line = stdin.readline()
        if not line:
            break
        try:
            text = line.decode("utf-8")
        except Exception:
            stdout.write('{"error":"event"}\n')
            stdout.flush()
            return 2
        stripped = text.strip()
        if stripped == "":
            stdout.write('{"error":"event"}\n')
            stdout.flush()
            return 2
        try:
            req = parse_json_text(text)
        except Exception:
            stdout.write('{"error":"event"}\n')
            stdout.flush()
            return 2
        try:
            resp = engine.handle(req, first)
        except EventError:
            stdout.write('{"error":"event"}\n')
            stdout.flush()
            return 2
        except Exception:
            stdout.write('{"error":"event"}\n')
            stdout.flush()
            return 2
        first = False
        stdout.write(json.dumps(resp, separators=(",", ":")))
        stdout.write("\n")
        stdout.flush()
    return 0


def main():
    args = sys.argv
    if len(args) >= 2 and args[1] == "compile":
        return cmd_compile()
    if len(args) == 3 and args[1] == "stream":
        return cmd_stream(args[2])
    return 2


if __name__ == "__main__":
    raise SystemExit(main())
